/// Function:<summary>
///             Copy ALL built in variables
///          </summary>
///
/// In:		 <param name="_pBuiltIn">Class to clone</param>
// #############################################################################################
yyBuiltIn.prototype.Copy = function (_pBuiltIn) {

	// Copy everything!!	
	for (var v = 0; v < _pBuiltIn.length; v++)
	{
		var p = _pBuiltIn[v];
		this[v] = p;
	}
};
