	get sprite_xoffset()  {
		// @if feature("sprites")
		var pSprite = g_pSpriteManager.Get(this.sprite_index);
		if (pSprite) return pSprite.xOrigin * this.image_xscale;
		// @endif sprites
		return 0;
	},

