    			graphics._drawImage(_pTPE.texture, _pTPE.x, _pTPE.y, _pTPE.w, _pTPE.h, _x + (ox * _xsc), _y + (oy * _ysc), _pTPE.CropWidth * _xsc, _pTPE.CropHeight * _ysc);
