var g_Gifs = [];



function gif_open(width, height, background_colour)
{
    var encoder = new GIFEncoder();

    encoder.setRepeat(0);
    encoder.setSize(yyGetInt32(width), yyGetInt32(height));
    encoder.start();
    for (var i = 0; i < g_Gifs.length; i++) {

        if (g_Gifs[i] == null) {
            g_Gifs[i] = encoder;
            return i;
        }
    }
    var ret =g_Gifs.length; 
    g_Gifs[g_Gifs.length] = encoder;
    return ret;


};

function gif_save_buffer(gif)
{
    // MissingFunction("gif_save_buffer()");

    gif = yyGetInt32(gif);

    var encoder = g_Gifs[gif];

    if (encoder == null)
        return -1;
    encoder.finish();
    var binary_gif = encoder.stream().getData();
    var pBuffer = buffer_create(binary_gif.length, eBuffer_Format_Grow, 1);
   
    if (pBuffer == null)
        return -1;

    //urgh
    for (var i = 0; i < binary_gif.length;i++)
        buffer_write(pBuffer, eBuffer_U8, binary_gif[i]);

    g_Gifs[gif] = null;

    return pBuffer;

};

function gif_save(gif, filename)
{
    //MissingFunction("gif_save()");

    gif = yyGetInt32(gif);

    var encoder = g_Gifs[gif];

    if (encoder == null)
        return;

    encoder.finish();
    encoder.download(yyGetString(filename));

  //  var binary_gif = encoder.stream().getData();
   // var data_url = 'data:image/gif;base64,'+encode64(binary_gif);
   // SaveTextFile_Block(filename, encode64(binary_gif));
    
     g_Gifs[gif] = null;
};

function gif_add_surface(gif, surface, delaytime, xoffset, yoffset, quantquality)
{
	// Optional params
	if (quantquality === undefined) quantquality = 2;
	if (xoffset === undefined) xoffset = 0;
	if (yoffset === undefined) yoffset = 0;

	var pSurf = g_Surfaces.Get(yyGetInt32(surface));
	
    if (pSurf != null) {

		if (pSurf.FrameBufferData.Texture.Format != eTextureFormat_A8R8G8B8)
        {
            debug("Surface " + yyGetInt32(_id) + " can't be used as a gif source as it uses unsupported format " + g_webGL.GetSurfaceFormatName(pSurf.FrameBufferData.Texture.Format));
            return -1;
        }
        var encoder = g_Gifs[yyGetInt32(gif)];

        if (encoder == null)
            return;

        switch (yyGetInt32(quantquality))
        {
            default:
                encoder.setQuality(1);
                break;
            case 0:
                encoder.setQuality(0);
                break;
            case 1:
                encoder.setQuality(30);
                break;
            case 2:
                encoder.setQuality(10);
                break;
        }

        encoder.setDelay(yyGetInt32(delaytime)*10);
        var singleimage = document.createElement(g_CanvasName);
        var pGraphics = singleimage.getContext('2d');
        Graphics_AddCanvasFunctions(pGraphics); 			// update for OUR functions.
		console.log(encoder.getWidth() + "-" + encoder.getHeight());
        var glTexture = g_webGL.CreateTextureFromFramebuffer(singleimage, pSurf.FrameBuffer, yyGetInt32(xoffset), yyGetInt32(yoffset), encoder.getWidth(), encoder.getHeight(), false, false, false);
        encoder.addFrame(Uint8ClampedArray.from(glTexture.Image), true);
    }
};

function yyRotationMatrix(angleDegrees)
{
	this.m_angleDegrees = angleDegrees;
	this.m_angleRadians = angleDegrees * Math.PI / 180.0;
	
	this.m_sin = Math.sin(this.m_angleRadians);
	this.m_cos = Math.cos(this.m_angleRadians);
}

yyRotationMatrix.prototype = {
	get angleDegrees() { return this.m_angleDegrees; },
	get angleRadians() { return this.m_angleRadians; },
	
	get matrix()
	{
		return [
			[ this.m_cos, -this.m_sin ],
			[ this.m_sin, this.m_cos ],
		];
	},
};

function RotatePointAroundOrigin(point_xy, origin_xy, angle)
{
	var point_x = point_xy[0];
	var point_y = point_xy[1];
	
	var origin_x = origin_xy[0];
	var origin_y = origin_xy[1];
	
	var rotated_x = angle.matrix[0][0] * (point_x - origin_x) + angle.matrix[0][1] * (point_y - origin_y) + origin_x;
	var rotated_y = angle.matrix[1][0] * (point_x - origin_x) + angle.matrix[1][1] * (point_y - origin_y) + origin_y;

	return [ rotated_x, rotated_y ];
}

