function CHashMapCalculateHash(snap)
{
	var hash = "";
	for (var i = 0; i < snap.length; i++)
	{
        var val = snap[i];
		hash += val.__type + val.sequenceObjectGlobalID.toString();
	}
	return hash;
}

function isIndex(_val)
{
    //if (_val.match('^\\d+$'))
    if (+_val == +_val)
        return true;
    else
        return false;
}

function EnhancedArray()
{    
    return new Proxy(new Array(), 
        {            
            get(target, prop, receiver)
            {                                    
                if ((target.GetIndex != undefined) && (isIndex(prop)))
                {
                    var index = yyGetInt32(prop);
                    return target.GetIndex(index);
                }
                else
                {
                    return Reflect.get(target, prop, receiver);
                }
            },
            set(target, prop, value, receiver)
            {
                if ((target.SetIndex != undefined) && (isIndex(prop)))
                {
                    var index = yyGetInt32(prop);
                    return target.SetIndex(index, value);
                }
                else
                {
                    return Reflect.set(target, prop, value, receiver);
                }
            }
        }
    );    
}

// Version of EnhancedArray that doesn't support a custom getter to reduce overhead
// This is for cases where we're just returning the value of the underlying array without any special handling
// It avoids calls to the isIndex() function
function EnhancedArrayNoGet() {
    return new Proxy(new Array(),
        {            
            set(target, prop, value, receiver) {
                if ((target.SetIndex != undefined) && (isIndex(prop))) {
                    var index = yyGetInt32(prop);
                    return target.SetIndex(index, value);
                }
                else {
                    return Reflect.set(target, prop, value, receiver);
                }
            }
        }
    );
}


// #############################################################################################
/// Function:<summary>
///             Constructor for the abstract the CSequenceBaseClass object whuch handles
///             dirtiness and signals when instances need to be updated due to changes.
///          </summary>
// #############################################################################################
// @if feature("sequences_min")
/** @constructor */
function CSequenceBaseClass()
{
	this.changeIndex = -1;
    this.globalChangeIndex = -1;
    this.sequenceObjectGlobalID = g_CurrSequenceObjectID++;
    this.__yyIsGMLObject = true;

    // Override Me
    this.UpdateDirtiness = function() {};
    
	this.IsDirty = function(_changeIndex)
	{
		if (this.globalChangeIndex < GetCurrSeqObjChangeIndex())
		{
			this.UpdateDirtiness();

			this.globalChangeIndex = GetCurrSeqObjChangeIndex();
		}

		if (_changeIndex < this.changeIndex)
			return true;
		else
			return false;
	};

	this.SignalChange = function()
	{		
		this.changeIndex = GetNextSeqObjChangeIndex();
	};
}

