/** @constructor */
function CSeqTrackAudioInfo()
{
    //this.keyindex = undefined;
    this.soundindex = -1;
    this.playdir = 1;
    this.emitterindex = -1;
}


// #############################################################################################
/// Function:<summary>
///             Create a new TrackEval object
///          </summary>
// #############################################################################################
/** @constructor */
function TrackEval() {

    this.matrix = new Matrix(); // This track evaluation's corresponding matrix
    this.matrixHeadPosition = -1; // The head position that was evaluated into this 
    this.overridden = 0; //override bit toggles
    this.hascreationvalue = new yyBitField64(); // one bit per track type denoting whether this node contains a value set via creation track 
    this.paramset = new yyBitField64();

    this.x = 0;
    this.y = 0;
    this.rotation = 0;
    this.scaleX = 1;
    this.scaleY = 1;
    this.xOrigin = 0;
    this.yOrigin = 0;
    this.gain = 1;
    this.pitch = 1;
    this.falloffRef = 100;
    this.falloffMax = 10000;
    this.falloffFactor = 1;
    //this.width = 0;
    //this.height = 0;
    this.imageIndex = 0;
    this.imageSpeed = 1;
    this.imageDistance = -1;

    this.colorMultiply = [];
    this.colorMultiply[0] = 1;
    this.colorMultiply[1] = 1;
    this.colorMultiply[2] = 1;
    this.colorMultiply[3] = 1;

    this.colorAdd = [];
    this.colorAdd[0] = 0;
    this.colorAdd[1] = 0;
    this.colorAdd[2] = 0;
    this.colorAdd[3] = 0;

    this.spriteIndex = -1;
    this.instanceID = OBJECT_NOONE;
    this.particleSystemID = -1; // particle tracks
    this.emitterIndex = -1;
    this.soundIndex = -1;
    this.pSequence = null;
    this.sequenceID = -1;

    this.FrameSizeX = 0;
    this.FrameSizeY = 0;
    this.CharacterSpacing = 0;
    this.LineSpacing = 0;
    this.ParagraphSpacing = 0;

    this.pFontEffectParams = new FontEffectParams();
}

TrackEval.prototype.ApplyCreationMask = function (_creationmask)
{
    this.hascreationvalue.AndEquals(_creationmask);
};

// #############################################################################################
/// Function:<summary>
///             Resets the TrackEval variables
///          </summary>
// #############################################################################################
TrackEval.prototype.ResetVariables = function ()
{
    this.x = 0;
    this.y = 0;  
    this.rotation = 0;
    this.scaleX = 1;
    this.scaleY = 1;
    this.xOrigin = 0;
    this.yOrigin = 0;
    this.gain = 1;
    this.pitch = 1;
    this.falloffRef = 100;
    this.falloffMax = 10000;
    this.falloffFactor = 1;
    this.imageIndex = 0;
    this.imageSpeed = 1;
    this.imageDistance = -1;
    this.colorMultiply[0] = 1;
    this.colorMultiply[1] = 1;
    this.colorMultiply[2] = 1;
    this.colorMultiply[3] = 1;
    this.colorAdd[0] = 0;
    this.colorAdd[1] = 0;
    this.colorAdd[2] = 0;
    this.colorAdd[3] = 0;

    this.FrameSizeX = 0;
    this.FrameSizeY = 0;
    this.CharacterSpacing = 0;
    this.LineSpacing = 0;
    this.ParagraphSpacing = 0;

    this.overridden = 0;
    this.hascreationvalue.ClearAllBits();
    this.paramset.ClearAllBits();
};

// #############################################################################################
/// Function:<summary>
///             Resets the TrackEval override flags
///          </summary>
// #############################################################################################
TrackEval.prototype.ResetOverrides = function () {
    this.overridden = 0;
};

// #############################################################################################
/// Function:<summary>
///             Sets the given override flag to the given value
///          </summary>
// #############################################################################################
TrackEval.prototype.Override = function (_track, _value) {
    switch(_track)
    {
        case eT_OriginX: if (_value) this.overridden |= (1 << 0); else this.overridden &= ~(1 << 0); break;
        case eT_OriginY: if (_value) this.overridden |= (1 << 1); else this.overridden &= ~(1 << 1); break;
        case eT_ImageSpeed: if (_value) this.overridden |= (1 << 2); else this.overridden &= ~(1 << 2); break;
        case eT_ImageIndex: if (_value) this.overridden |= (1 << 3); else this.overridden &= ~(1 << 3); break;        
    }
};

// #############################################################################################
/// Function:<summary>
///             Returns whether the given override flag is set
///          </summary>
// #############################################################################################
TrackEval.prototype.Overrides = function (_track) {
    switch (_track) {
        case eT_OriginX: return (this.overridden & (1 << 0)) != 0;
        case eT_OriginY: return (this.overridden & (1 << 1)) != 0;
        case eT_ImageSpeed: return (this.overridden & (1 << 2)) != 0;
        case eT_ImageIndex: return (this.overridden & (1 << 3)) != 0;        
    }
};

