var eBuffer_GeneralError = -1,
    eBuffer_OutOfSpace = -2,
    eBuffer_OutOfBounds = -3,
    eBuffer_InvalidType = -4,
    eBuffer_UnknownBuffer = -5;

var eBuffer_Format_Fixed = 0,
    eBuffer_Format_Grow = 1,
    eBuffer_Format_Wrap = 2,
    eBuffer_Format_Fast = 3,
    eBuffer_Format_VBuffer = 4;

var eBuffer_None = 0,
	eBuffer_U8 = 1,
	eBuffer_S8 = 2,
	eBuffer_U16 = 3,
	eBuffer_S16 = 4,
	eBuffer_U32 = 5,
	eBuffer_S32 = 6,
	eBuffer_F16 = 7,
	eBuffer_F32 = 8,
	eBuffer_F64 = 9,
	eBuffer_Bool = 10,
	eBuffer_String = 11,
	eBuffer_U64 = 12,
    eBuffer_Text = 13;


var eBuffer_Start = 0,
	eBuffer_Relative = 1,
	eBuffer_End = 2;

// #############################################################################################
/// Function:<summary>
///          	Base64 decode into a binbuffer
///          </summary>
///
/// In:		 <param name="data">data to be decoded</param>
///    		 <param name="_out_len">lenth of output buffer</param>
///    		 <param name="_pBuffer">byte buffer (or array) to decode INTO</param>
///    		 <param name="_offset">start offset into destination buffer to decode at</param>
///    		 <param name="_add_null">add a 0x00 at the end of the stream?</param>
/// Out:	<returns>
///				The decoded buffer
///			</returns>
// #############################################################################################
function Base64DecodeBin(data, _out_len, _pBuffer, _out_offset, _add_null, _in_byte_offset) 
{
    // http://kevin.vanzonneveld.net
    // +   original by: Tyler Akins (http://rumkin.com)
    // +   improved by: Thunder.m
    // +      input by: Aman Gupta
    // +   improved by: Kevin van Zonneveld (http://kevin.vanzonneveld.net)
    // +   bugfixed by: Onno Marsman
    // +   bugfixed by: Pellentesque Malesuada
    // +   improved by: Kevin van Zonneveld (http://kevin.vanzonneveld.net)
    // +      input by: Brett Zamir (http://brett-zamir.me)
    // +   bugfixed by: Kevin van Zonneveld (http://kevin.vanzonneveld.net)
    // *     example 1: base64_decode('S2V2aW4gdmFuIFpvbm5ldmVsZA==');
    // *     returns 1: 'Kevin van Zonneveld'
    // mozilla has this native
    // - but breaks in 2.0.0.12!
    //if (typeof this.window['atob'] == 'function') {
    //    return atob(data);
    //}
    var b64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=";
    var o1, o2, o3, h1, h2, h3, h4, bits;
    var i = 0;
    var ac = _out_offset;
    var dec = "";

    var start_block = Math.floor(_in_byte_offset / 3);
    i = start_block * 4;

    var discard = _in_byte_offset % 3;


    if (!data) {
        return data;
    }


    data += '';
    do {
        // unpack four hexets into three octets using index points in b64

        // Looping around these allows us to get rid of invalid characters - like newlines!
        h1 = h2 = h3 = h4 = -1;
        while (h1 < 0) {
            h1 = b64.indexOf(data.charAt(i++));     // returns -1 if not valid
        }
        while (h2 < 0) {
            h2 = b64.indexOf(data.charAt(i++));
        }
        while (h3 < 0) {
            h3 = b64.indexOf(data.charAt(i++));
        }
        while (h4 < 0) {
            h4 = b64.indexOf(data.charAt(i++));
        }

        var chr1 = (h1 << 2) | (h2 >> 4);
        var chr2 = ((h2 & 15) << 4) | (h3 >> 2);
        var chr3 = ((h3 & 3) << 6) | h4;

        _pBuffer[ac++] = chr1;
        if (ac >= _out_len) return _pBuffer;
        if (h3 != 64) {
            _pBuffer[ac++] = chr2;
            if (ac >= _out_len) return _pBuffer;
        }
        if (h4 != 64) {
            _pBuffer[ac++] = chr3;
            if (ac >= _out_len) return _pBuffer;
        }
    } while (i < data.length);

    var out_ = ac;
    if (_add_null && out_ < _out_len) {
        _pBuffer[out_++] = '\0';
    }
    return _pBuffer;
}



// #############################################################################################
/// Property: <summary>
///              
///           </summary>
// #############################################################################################
function Base64Encode(input, length)
{        
    var _keyStr = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=";

    var output = "";
    var chr1, chr2, chr3 = "";
    var enc1, enc2, enc3, enc4 = "";
    var i = 0;

    do {
       chr1 = input.charCodeAt(i++);
       chr2 = input.charCodeAt(i++);
       chr3 = input.charCodeAt(i++);
       enc1 = chr1 >> 2;

       enc2 = ((chr1 & 3) << 4) | (chr2 >> 4);
       enc3 = ((chr2 & 15) << 2) | (chr3 >> 6);
       enc4 = chr3 & 63;

       if (isNaN(chr2)) {
          enc3 = enc4 = 64;
       } 
       else if (isNaN(chr3)) {
          enc4 = 64;
       }

       output = output +
          _keyStr.charAt(enc1) +
          _keyStr.charAt(enc2) +
          _keyStr.charAt(enc3) +
          _keyStr.charAt(enc4);

       chr1 = chr2 = chr3 = "";
       enc1 = enc2 = enc3 = enc4 = "";

    } while (i < length);

    return output;
}

// #############################################################################################
/// Function:<summary>
///             Get the next POW2 texture size
///          </summary>
///
/// In:		 <param name="_size"></param>
/// Out:	 <returns>
///				
///			 </returns>
// #############################################################################################
function GetPOW2Alignment( _size )
{
	var	size = 1;
	while(size<=1024)
	{
		if( _size <= size ) return size;
		size = size << 1;
	}
	return 1024;	
}


// #############################################################################################
/// Function:<summary>
///             Fix buffers for Chrome, Firefox, Opera and Safari
///          </summary>
// #############################################################################################
/** @constructor */
function yyBuffer( _size, _type, _alignment, _srcbytebuff ) {

    _alignment = GetPOW2Alignment(_alignment & 0x1ff);

    this.m_RealSize = _size + _alignment;   
    
   
	this.m_Type = _type;
	this.m_Size = _size;
	this.m_Alignment = _alignment;
	this.m_AlignmentOffset = 0;
	this.m_BufferIndex = 0;
	this.m_UsedSize = 0;
	
    // Allocate	type conversion buffers	
	this.m_pRAWUnderlyingBuffer = new ArrayBuffer(_size);
	this.m_DataView = new DataView(this.m_pRAWUnderlyingBuffer);

    //fill with provided Uint8Array
	if (_srcbytebuff != undefined && _srcbytebuff.length > 0)
	{
	    var fillSize = yymin(_srcbytebuff.length, _size);
	    this.m_UsedSize = fillSize;
	    var dstbytebuff = new Uint8Array(this.m_pRAWUnderlyingBuffer);
	    for (var i = 0; i < fillSize; i++) {
	        dstbytebuff[i] = _srcbytebuff[i];
	    }
	}
}


// #################################################################################################
/// Function: yygetFloat16
/// Description:
///     Retrieve and decode a 16-bit floating-point number from a DataView.
///
/// Parameters:
///     byteOffset - The offset where the 16-bit float is stored.
///     littleEndian - Specifies the endianness of the data (true for little-endian, false for big-endian).
///
/// Returns:
///     The decoded 16-bit floating-point number.
///     If the input data is invalid or out of range, NaN is returned.
// #################################################################################################
DataView.prototype.yygetFloat16 = function (byteOffset, littleEndian) {
    // byteOffset: The offset where the 16-bit float is stored
    // littleEndian: Specifies the endianness of the data

    // Used references: https://en.wikipedia.org/wiki/Half-precision_floating-point_format

    // Read the 16-bit float as an unsigned integer
    const uint16 = this.getUint16(byteOffset, littleEndian);

    // Extract the sign bit (bit 15)
    const sign = (uint16 & 0x8000) ? -1 : 1;

    // Extract the exponent bits (bits 10-14)
    const exponent = (uint16 >> 10) & 0x1F;

    // Extract the mantissa bits (bits 0-9)
    const mantissa = uint16 & 0x3FF;

    if (exponent === 0) {
        // If exponent is 0, it's a denormalized number or zero
        if (mantissa === 0) {
            // Zero
            return sign * 0.0;
        } else {
            // Denormalized number
            // Calculate the value using the formula for denormalized numbers
            return sign * Math.pow(2, -14) * (mantissa / 1024);
        }
    } else if (exponent === 31) {
        // If exponent is 31, it's infinity or NaN
        if (mantissa === 0) {
            // Positive or negative infinity
            return (sign === 1) ? Infinity : -Infinity;
        } else {
            // NaN
            return NaN;
        }
    } else {
        // Normalized number
        // Calculate the value using the formula for normalized numbers
        return sign * Math.pow(2, exponent - 15) * (1 + mantissa / 1024);
    }
};

// #################################################################################################
/// Function: yysetFloat16
/// Description:
///     Encode and write a 16-bit floating-point number (float16) to a DataView.
///
/// Parameters:
///     offset - The offset where the float16 will be written in the DataView.
///     value - The float16 value to encode and write.
///     littleEndian - Optional. Specifies the endianness of the data (true for little-endian, false for big-endian).
///
/// Returns:
///     None.
///
/// Details:
///     The function encodes the provided float16 value as per IEEE 754-2008 standard for half-precision
///     floating-point numbers and writes it to the specified offset in the DataView. If the value is
///     outside the representable range for float16, a RangeError is thrown.
///
///     Special cases:
///     - If the value is 0, it is written as a positive zero.
///     - If the value is NaN, it is written as the NaN representation.
///
/// Example Usage:
///     const dataView = new DataView(new ArrayBuffer(2));
///     dataView.yysetFloat16(0, 1.0, true); // Write float16 value 1.0 in little-endian
// #################################################################################################
DataView.prototype.yysetFloat16 = function(offset, value, littleEndian = true) {
    let sign = 0;
    let exponent = 0;
    let mantissa = 0;

    // Used references: https://en.wikipedia.org/wiki/Half-precision_floating-point_format
    if (isNaN(value)) {
        // If the value is NaN, use the standard NaN representation for float16.
        mantissa = 0x200;
        exponent = 0x1F;
    } else if (value === Infinity || value === -Infinity) {
        // Handling Infinity.
        exponent = 0x1F;
    } else if (value === 0) {
        // Handling zero (both positive and negative).
        sign = (1 / value === -Infinity) ? 0x8000 : 0;
    } else {
        sign = value < 0 ? 0x8000 : 0;
        value = Math.abs(value);

        if (value >= Math.pow(2, -14)) {
            // Handle normal numbers.
            let exponentAndMantissa = Math.floor(Math.log2(value) + 15);
            exponent = exponentAndMantissa;
            mantissa = Math.floor((value / Math.pow(2, exponent - 15) - 1) * 1024);

            if (mantissa === 1024) {
                // We might end in an exponent overflow state.
                exponentAndMantissa += 1;
                exponent = exponentAndMantissa;
                mantissa = 0;
            }

            // Check if we overflow into Infinity.
            if (exponentAndMantissa > 30) {
                // Handle overflow to Infinity.
                exponent = 0x1F;
                mantissa = 0;
            }
        } else {
            // Handle subnormal numbers.
            mantissa = Math.floor(value / Math.pow(2, -24));
        }
    }

    const float16 = sign | (exponent << 10) | mantissa;
    this.setUint16(offset, float16, littleEndian);
};



// #############################################################################################
/// Function:<summary>
///          	Return the size of a "type"
///          </summary>
///
/// In:		<param name="_type">Type to get the size of</param>
/// Out:	<returns>
///				size or -1 for error 
///			</returns>
// #############################################################################################
function BUfferTypeSizeOf( _type )
{
	switch( _type ){
		case eBuffer_U8:	
		case eBuffer_S8:
		case eBuffer_Bool:	return 1;
		case eBuffer_U16:
		case eBuffer_S16:	
		case eBuffer_F16:	return 2;
		case eBuffer_U32:
		case eBuffer_S32:	
		case eBuffer_F32:	return 4;
		case eBuffer_F64:	return 8;
	}
	return -1;
}


// #############################################################################################
/// Function:<summary>
///          </summary>
// #############################################################################################
yyBuffer.prototype.yyb_resize = function(newSize) {

    var NewBuff = new ArrayBuffer(newSize);

    var oldbuf = new Uint8Array(this.m_pRAWUnderlyingBuffer);
    var newbuf = new Uint8Array(NewBuff);

    // buffer.set() does not like sizing down... so do manually
    if (this.m_pRAWUnderlyingBuffer.byteLength > newSize) {
        for (var i = 0; i < newSize; i++) {
            newbuf[i] = oldbuf[i];
        }
    } else {
        newbuf.set(oldbuf);
    }
    this.m_pRAWUnderlyingBuffer = NewBuff;

    this.m_DataView = new DataView(this.m_pRAWUnderlyingBuffer); //Prolly need to reset this.
    this.m_Size = newSize;

    this.yyb_UpdateUsedSize(-1);
};


// #############################################################################################
/// Function:<summary>
///          	Update the "used" size of a buffer
///          </summary>
///
/// In:		<param name="_size">new size (or undefined)</param>
/// In:		<param name="_reset">reset flag(or undefined)</param>
// #############################################################################################
yyBuffer.prototype.yyb_UpdateUsedSize = function(_size, _reset)
{
    if (_size == undefined) _size = -1;
    if (_reset == undefined) _reset = false;


    var size = _size;
    if (size == -1) size = this.m_BufferIndex;
    if (_reset) {
        this.m_UsedSize = size;
    } else {
        this.m_UsedSize = yymax(this.m_UsedSize, size);
        this.m_UsedSize = yymin(this.m_UsedSize, this.m_Size);
    }
};




// #############################################################################################
///  Function:<summary>
///             Convert string to UTF-8 format.
///             Hi to low order (so in 2 byte format, first byte is the upper 5 bits of the char)
///           </summary>
//
// NumBytes  NumBits   First   Last     Byte 1	    Byte 2      Byte 3     Byte 4
// 1	       7	   U+0000   U+007F   0xxxxxxx
// 2	      11       U+0080   U+07FF   110xxxxx   10xxxxxx		
// 3	      16       U+0800   U+FFFF   1110xxxx   10xxxxxx    10xxxxxx	
// 4	      21       U+10000  U+10FFFF 11110xxx   10xxxxxx    10xxxxxx   10xxxxxx
// 
// #############################################################################################
function UnicodeToUTF8(_str) {
    var txt = "";
    for (var i = 0; i < _str.length; i++) {
        var charCode = _str.codePointAt(i);
        if (charCode < 0x80) {
            txt += String.fromCharCode(charCode & 0x7f);
        } else if (charCode < 0x0800) {
            txt += String.fromCharCode((((charCode >> 6) & 0x1f) | 0xc0));
            txt += String.fromCharCode((charCode & 0x3f) | 0x80);
        } else if (charCode < 0xd800 || charCode >= 0xe000) {
            txt += String.fromCharCode(((charCode >> 12) & 0x0f) | 0xe0);
            txt += String.fromCharCode(((charCode >> 6) & 0x3f) | 0x80);
            txt += String.fromCharCode((charCode & 0x3f) | 0x80);
        } else {
            txt += String.fromCharCode(((charCode >> 18) & 0x07) | 0xf0);
            txt += String.fromCharCode(((charCode >> 12) & 0x3f) | 0x80);
            txt += String.fromCharCode(((charCode >> 6) & 0x3f) | 0x80);
            txt += String.fromCharCode((charCode & 0x3f) | 0x80);
            i++;  // Skip the low surrogate in the next iteration
        }
    }
    return txt;
}


// #############################################################################################
/// Function:<summary>
///          	Return the size of a "type"
///          </summary>
///
/// In:		<param name="_type">Type to get the size of</param>
/// Out:	<returns>
///				size or -1 for error 
///			</returns>
// #############################################################################################
yyBuffer.prototype.yyb_read = function(_type) {


    // Deal with basic alignment first
    //m_BufferIndex = (m_BufferIndex + (m_Alignment-1)) & ~(m_Alignment-1);		// align
    this.m_BufferIndex = (((this.m_BufferIndex + this.m_AlignmentOffset) + (this.m_Alignment - 1)) & ~(this.m_Alignment - 1)) - this.m_AlignmentOffset; 	// align
    if (this.m_BufferIndex >= this.m_Size && this.m_Type == eBuffer_Format_Wrap) {
        // while loop incase its a stupid alignment on a small buffer
        while (this.m_BufferIndex >= this.m_Size) {
            this.yyb_calcnextalignmentoffset();
            this.m_BufferIndex -= this.m_Size;
        }
    }

    // Out of space?
    if (this.m_BufferIndex >= this.m_Size) return (_type==eBuffer_String) ? "" : eBuffer_OutOfBounds;

    var res;
    switch (_type) {
        case eBuffer_Bool:
            res = this.m_DataView.getUint8(this.m_BufferIndex++);
            if (res == 1) {
                res = true;
            } else {
                res = false;
            }
            break;
        case eBuffer_U8:
            {
                res = this.m_DataView.getUint8(this.m_BufferIndex++);
            }
            break;
        case eBuffer_String:
        case eBuffer_Text:
            {
                res = "";
                var chr;
                var chrCode = 0;

                while(this.m_BufferIndex<this.m_UsedSize)
                {
                    var v = 0;
                    chr = -1;
                    chrCode = this.m_DataView.getUint8(this.m_BufferIndex++, true);

                    if ((chrCode & 0x80) == 0) {
                        v = chrCode;
                    } else if ((chrCode & 0xe0) == 0xc0) {
                        v = (chrCode&0x1f)<<6;
                        chrCode = this.m_DataView.getUint8(this.m_BufferIndex++, true);
                        v |= (chrCode & 0x3f);

                    } else if ((chrCode & 0xf0) == 0xe0) {
                        v = (chrCode & 0x0f)<<12;
                        chrCode = this.m_DataView.getUint8(this.m_BufferIndex++, true);
                        v |= (chrCode & 0x3f) << 6;
                        chrCode = this.m_DataView.getUint8(this.m_BufferIndex++, true);
                        v |= (chrCode & 0x3f);

                    } else {
                        v = (chrCode & 0x07)<<18;
                        chrCode = this.m_DataView.getUint8(this.m_BufferIndex++, true);
                        v |= (chrCode & 0x3f) << 12;
                        chrCode = this.m_DataView.getUint8(this.m_BufferIndex++, true);
                        v |= (chrCode & 0x3f) << 6;
                        chrCode = this.m_DataView.getUint8(this.m_BufferIndex++, true);
                        v |= (chrCode & 0x3f);
                        chr = String.fromCharCode((v >> 10) + 0xD7C0) + String.fromCharCode((v & 0x3FF) | 0xDC00);
                    }
                    if (v == 0x00) break;
                    if(chr < 0) chr = String.fromCharCode(v);
                    res += chr;
                }
            }
            break;
        case eBuffer_S8:
            res = this.m_DataView.getInt8(this.m_BufferIndex++);
            break;

        case eBuffer_U16:
            res = this.m_DataView.getUint16(this.m_BufferIndex, true);
            this.m_BufferIndex += 2;
            break;
        case eBuffer_S16:
            res = this.m_DataView.getInt16(this.m_BufferIndex, true);
            this.m_BufferIndex += 2;
            break;

        case eBuffer_S32:
            res = this.m_DataView.getInt32(this.m_BufferIndex, true);
            this.m_BufferIndex += 4;
            break;
        case eBuffer_U32:
            res = new Long( this.m_DataView.getUint32(this.m_BufferIndex, true), 0);
            this.m_BufferIndex += 4;
            break;

        case eBuffer_F16:
            res = this.m_DataView.yygetFloat16(this.m_BufferIndex, true);
            this.m_BufferIndex += 2;
            break;
        case eBuffer_F32:
            res = this.m_DataView.getFloat32(this.m_BufferIndex, true);
            this.m_BufferIndex += 4;
            break;
        case eBuffer_F64:
            res = this.m_DataView.getFloat64(this.m_BufferIndex, true);
            this.m_BufferIndex += 8;
            break;
            
        case eBuffer_U64:
            var low = this.m_DataView.getUint32(this.m_BufferIndex, true);
            this.m_BufferIndex += 4;
            var high = this.m_DataView.getUint32(this.m_BufferIndex, true);
            this.m_BufferIndex += 4;
            res = new Long(low, high);
            break;

    }
    return res;
};

// #############################################################################################
/// Function:<summary>
///          </summary>
// #############################################################################################
yyBuffer.prototype.yyb_calcnextalignmentoffset = function() {
    this.m_AlignmentOffset = (this.m_AlignmentOffset + this.m_Size) % this.m_Alignment;
};


// #############################################################################################
/// Function:<summary>
///          </summary>
// #############################################################################################
function BufferSizeOf(_type) {

    var sizeneeded = 0;
    
    switch (_type) {

        case eBuffer_Bool:
        case eBuffer_U8:
        case eBuffer_S8:
            sizeneeded = 1;
            break;

        case eBuffer_F16:
        case eBuffer_U16:
        case eBuffer_S16:
            sizeneeded = 2;
            break;

        case eBuffer_S32:
        case eBuffer_U32:
        case eBuffer_F32:
            sizeneeded = 4;
            break;

        case eBuffer_F64:
        case eBuffer_U64:
            sizeneeded = 8;
            break;

    }

    return sizeneeded;

}

// @if function("buffer_md5")
function yyMD5(){
    this.i = new Uint32Array(2);   //[2];       //uint32
    this.buf = new Uint32Array(4); //[4];    //uint32
    this.IN = new Uint8Array(64);       //[64];     //unsigned char
    this.digest=new Uint8Array(16);   // [16];   //unsigned char
    
    this.i[0]=this.i[1]=0;
    this.buf[0] = this.buf[1] = this.buf[2] = this.buf[3] = 0;
    for(var i=0;i<64;i++) this.IN[i]=0;
    for(var i=0;i<16;i++) this.digest[i]=0;
}


// get the digest as a hex string
yyMD5.prototype.yyb_hex = function() 
{
    var hh = "0123456789abcdef";
    var s="";
	for(var h=0;h<16;h++){
	    var b = this.digest[h];
	    s += hh[((b>>4)&0xf)];
	    s += hh[(b&0xf)];
	}
	return s;
};

function _initmd5()
{
    var mdContext = new yyMD5();
    mdContext.i[0] = mdContext.i[1] = 0;

    /* Load magic initialization constants.
    */
    mdContext.buf[0] = 0x67452301;
    mdContext.buf[1] = 0xefcdab89;
    mdContext.buf[2] = 0x98badcfe;
    mdContext.buf[3] = 0x10325476;
    return mdContext;
}
var md5_temp_var = new Uint32Array(16);


// F, G and H are basic MD5 functions: selection, majority, parity
function md5_F(x, y, z){    
    md5_temp_var[0] = x;
    md5_temp_var[1] = y;
    md5_temp_var[2] = z;
     return ( ((md5_temp_var[0]) & (md5_temp_var[1])) | ((~md5_temp_var[0]) & (md5_temp_var[2])) );
}
function md5_G(x, y, z){
    md5_temp_var[0] = x;
    md5_temp_var[1] = y;
    md5_temp_var[2] = z;
    return ( ((md5_temp_var[0]) & (md5_temp_var[2])) | ((md5_temp_var[1]) & (~md5_temp_var[2])) );
}
function md5_H(x, y, z){
    md5_temp_var[0] = x;
    md5_temp_var[1] = y;
    md5_temp_var[2] = z;
    return ((md5_temp_var[0]) ^ (md5_temp_var[1]) ^ (md5_temp_var[2]));
}
function md5_I(x, y, z){
    md5_temp_var[0] = x;
    md5_temp_var[1] = y;
    md5_temp_var[2] = z;
    return ((md5_temp_var[1]) ^ ((md5_temp_var[0]) | (~md5_temp_var[2])));
}




// ROTATE_LEFT rotates x left n bits
var md5_x_n= new Uint32Array(2);
function md5_ROTATE_LEFT(x, n) {    
    md5_x_n[0] = x;
    md5_x_n[1] = ((md5_x_n[0]<<n)&0xffffffff) | ((md5_x_n[0]>>(32-n))&((1<<n)-1));      // might have to MASK these bits off
    return md5_x_n[1];
}


// FF, GG, HH, and II transformations for rounds 1, 2, 3, and 4
// Rotation is separate from addition to prevent recomputation 
var md5_var_a= new Uint32Array(7);
function md5_FF(a, b, c, d, x, s, ac)
{
    md5_var_a[0] = a;
    md5_var_a[1] = b;
    md5_var_a[2] = c;
    md5_var_a[3] = d;
    md5_var_a[4] = x;
    md5_var_a[5] = s;
    md5_var_a[6] = ac;
    md5_var_a[0] += md5_F( md5_var_a[1], md5_var_a[2], md5_var_a[3]) + md5_var_a[4] + (md5_var_a[6]);
    md5_var_a[0] = md5_ROTATE_LEFT(md5_var_a[0], md5_var_a[5] );
    md5_var_a[0] += md5_var_a[1];
    return md5_var_a[0];
}
function md5_GG(a, b, c, d, x, s, ac)
{
    md5_var_a[0] = a;
    md5_var_a[1] = b;
    md5_var_a[2] = c;
    md5_var_a[3] = d;
    md5_var_a[4] = x;
    md5_var_a[5] = s;
    md5_var_a[6] = ac;
    md5_var_a[0] += md5_G(md5_var_a[1], md5_var_a[2], md5_var_a[3]) + md5_var_a[4] + (md5_var_a[6]); 
    md5_var_a[0] = md5_ROTATE_LEFT(md5_var_a[0], md5_var_a[5]); 
    md5_var_a[0] += md5_var_a[1];
    return md5_var_a[0];
}
function md5_HH(a, b, c, d, x, s, ac)
{
    md5_var_a[0] = a;
    md5_var_a[1] = b;
    md5_var_a[2] = c;
    md5_var_a[3] = d;
    md5_var_a[4] = x;
    md5_var_a[5] = s;
    md5_var_a[6] = ac;
    md5_var_a[0] += md5_H( md5_var_a[1], md5_var_a[2], md5_var_a[3]) + md5_var_a[4] + (md5_var_a[6]);
    md5_var_a[0] = md5_ROTATE_LEFT(md5_var_a[0], md5_var_a[5]);
    md5_var_a[0] += md5_var_a[1];
    return md5_var_a[0];
}
function md5_II(a, b, c, d, x, s, ac)
{
    md5_var_a[0] = a;
    md5_var_a[1] = b;
    md5_var_a[2] = c;
    md5_var_a[3] = d;
    md5_var_a[4] = x;
    md5_var_a[5] = s;
    md5_var_a[6] = ac;
    md5_var_a[0] += md5_I( md5_var_a[1], md5_var_a[2], md5_var_a[3] ) + md5_var_a[4] + (md5_var_a[6]);
    md5_var_a[0] = md5_ROTATE_LEFT(md5_var_a[0], md5_var_a[5]);
    md5_var_a[0] += md5_var_a[1];
    return md5_var_a[0];
}

// Basic MD5 step. Transform buf based on in.
