// @if function("buffer_crc32")
function crc32_init() { 
    var poly = -306674912; 
    var tab = new Array(256); 
    for (var i = 0; i < 256; i++) { 
        var crc = i; 
        var times = 8; 
        while (--times >= 0) { 
            if ((crc & 1) != 0) { 
                crc = crc >>> 1 ^ poly; 
            } else 
                crc >>>= 1; 
        } 
        tab[i] = crc; 
    } 
    return tab; 
}
 
var crc32_tab = crc32_init(); 
function crc32(b, pos, len) { 
    var crc = 0xffffffff;
    var tab = crc32_tab; 
    var i = pos; 
    for (var _g1 = pos + len; i < _g1; i++) 
        crc = (tab[(crc ^ b[i]) & 255] ^ ((crc >>> 8) & 0x00ffffff)) >>> 0;
    return crc; 
}
