function buffer_seek(buffer, base, offset) {

    var pBuff = g_BufferStorage.Get(yyGetInt32(buffer));
    if (!pBuff) return 0;

    return pBuff.yyb_seek(yyGetInt32(base), yyGetInt32(offset));
}

