function buffer_peek(buffer, offset, type) {

    var pBuff = g_BufferStorage.Get(yyGetInt32(buffer));
    if (!pBuff) return 0;
    return pBuff.yyb_peek(yyGetInt32(type), yyGetInt32(offset));
}

