// #############################################################################################
// Function:
//              Copy bytes from one buffer to another
//          </summary>
//  In:     _pDest          Destination Buffer
//          _pSrc           Source Buffer
//          _src_mem_size   How big is the memory buffer?
//          _src_offset     offset into buffer
//          _src_size       Number of bytes to try and copy
//          _dest_offset    Destination offset
//          _grow           Grow dest buffer?
//          _wrap           Wrap dest buffer?
//          _src_wrap       Source is a wrapping buffer?
//
// #############################################################################################
function CopyMemoryToBuffer(_pDest, _pSrc, _src_mem_size, _src_offset, _src_size, _dest_offset, _grow, _wrap, _src_wrap)
{

	if (_src_mem_size <= 0)
		return 0;

	// Clamp source offset and size to valid values	
	if (_src_size < 0)
	    _src_size = _src_mem_size;


	if (_src_wrap) {
	    while (_src_offset < 0)
	        _src_offset += _src_mem_size;

	    while (_src_offset >= _src_mem_size)
	        _src_offset -= _src_mem_size;

	    if ((_src_offset + _src_size) <= _src_mem_size)
	        _src_wrap = false;	// no need to wrap the source
	}
	else
	{
	    if (_src_offset < 0)
	        _src_offset = 0;

	    if (_src_offset >= _src_mem_size)
	        _src_offset = _src_mem_size - 1;

	    if ((_src_offset + _src_size) > _src_mem_size)
	        _src_size = _src_mem_size - _src_offset;
	}
	
	var dest_size = _src_size;	

	// Clamp dest offset and dest size to valid values
	if (!_grow)
	{
		if (_pDest.m_Size <= 0)
		{
			// This'll never work - bail			
			return 0;
		}		

		if (_wrap)
		{
			while(_dest_offset < 0)
				_dest_offset += _pDest.m_Size;

			while(_dest_offset >= _pDest.m_Size)
				_dest_offset -= _pDest.m_Size;			

			if ((_dest_offset + dest_size) <= _pDest.m_Size)
				_wrap = false;	// disable wrapping if the source data won't extend past the edge of the buffer
		}
		else
		{
			if (_dest_offset < 0)
				_dest_offset = 0;

			if (_dest_offset >= _pDest.m_Size)
				_dest_offset = _pDest.m_Size - 1;				

			if ((_dest_offset + dest_size) > _pDest.m_Size)
				dest_size = _pDest.m_Size - _dest_offset;
		}
	}
	else
	{
		// Work out if we need to resize the buffer
		if (_dest_offset < 0)
			_dest_offset = 0;

		if ((_dest_offset + dest_size) > _pDest.m_Size)
		{
			// Resize the buffer
			var newsize = _dest_offset + dest_size;
			_pDest.yyb_resize( newsize );					
		}
	}
							
	//m_BufferIndex = 0;			

    var srcbytebuff = new Uint8Array(_pSrc.m_pRAWUnderlyingBuffer);
    var dstbytebuff = new Uint8Array(_pDest.m_pRAWUnderlyingBuffer);
    var i;
	if (_wrap || _src_wrap)
	{
		var amountToCopy = dest_size;
		while(amountToCopy > 0)
		{
			var amountToCopyNow = yymin(amountToCopy, (_pDest.m_Size - _dest_offset));
			amountToCopyNow = yymin(amountToCopyNow, _src_mem_size - _src_offset);
			
			 for (i = 0; i < amountToCopyNow; i++) {
                dstbytebuff[_dest_offset + i] = srcbytebuff[_src_offset + i];
            }
			//memcpy(_pDest->m_pMemory + _dest_offset, _pSrcMem + _src_offset, amountToCopyNow);				
			 _dest_offset += amountToCopyNow;
			 this.yyb_UpdateUsedSize(_dest_offset);
			_src_offset += amountToCopyNow;
			_dest_offset = _dest_offset % _pDest.m_Size;
			_src_offset = _src_offset % _src_mem_size;
			amountToCopy -= amountToCopyNow;
		}
	}
	else
	{
	
	    for (i = 0; i < _src_mem_size; i++) {
	        dstbytebuff[_dest_offset + i] = srcbytebuff[_src_offset + i];
	    }
	    _pDest.yyb_UpdateUsedSize(_dest_offset + dest_size);
		//memcpy(_pDest->m_pMemory + _dest_offset, _pSrcMem + _src_offset, dest_size);	
	}

	return 1;	// success!
}

// #############################################################################################
/// Function:<summary>
///          </summary>
// #############################################################################################
function buffer_copy(src_buffer, src_offset, size, dest_buffer, dest_offset) {

    var pBuff = g_BufferStorage.Get(yyGetInt32(src_buffer));
    if (!pBuff) 
        return eBuffer_UnknownBuffer;

    var pDestBuff = g_BufferStorage.Get(yyGetInt32(dest_buffer));
    if (!pDestBuff)
        return eBuffer_UnknownBuffer;

  	var grow;
	if ((pDestBuff.m_Type == eBuffer_Format_Grow) || (pDestBuff.m_Size == 0))
		grow = true;
	else
		grow = false;

	var wrap;
	if (pDestBuff.m_Type == eBuffer_Format_Wrap)
		wrap = true;
	else
		wrap = false;

	var src_wrap;
	if (pBuff.m_Type == eBuffer_Format_Wrap)
		src_wrap = true;
	else
		src_wrap = false;

    //function CopyMemoryToBuffer(_pDest, _pSrc, _src_mem_size, _src_offset, _src_size, _dest_offset, _grow, _wrap, _src_wrap)
	var success = CopyMemoryToBuffer(pDestBuff, pBuff, pBuff.m_Size, yyGetInt32(src_offset), yyGetInt32(size), yyGetInt32(dest_offset), grow, wrap, src_wrap);

}

function _WrapIndex(index, size)
{
	return (index % size + size) % size;
}

// #############################################################################################
/// Function:<summary>
///             Copies number of elements with given stride from the source buffer to the destination
///             buffer. Stride between copied elements can be different in the destination buffer
///             than in the source buffer.
///          </summary>
// #############################################################################################
function buffer_copy_stride(_src_buffer, _src_offset, _src_size, _src_stride, _src_count, _dest_buffer, _dest_offset, _dest_stride)
{
    var srcIndex = yyGetInt32(_src_buffer);
    var srcBuffer = g_BufferStorage.Get(srcIndex);
    if (!srcBuffer)
    {
        yyError("Illegal Source Buffer Index " + srcIndex);
        return;
    }

    _src_offset = yyGetInt32(_src_offset);
    if (_src_offset < 0)
    {
        src_offset = _WrapIndex(_src_offset, srcBuffer.m_Size);
    }

    _src_size = yyGetInt32(_src_size);
    if (_src_size < 0)
    {
        yyError("Size cannot be a negative number");
        return;
    }

    _src_stride = yyGetInt32(_src_stride);

    _src_count = yyGetInt32(_src_count);
    if (_src_count < 0)
    {
        yyError("Count cannot be a negative number");
        return;
    }

    var destIndex = yyGetInt32(_dest_buffer);
    var destBuffer = g_BufferStorage.Get(destIndex);
    if (!destBuffer)
    {
        yyError("Illegal Destination Buffer Index " + destIndex);
        return;
    }

    if (srcBuffer == destBuffer)
    {
        yyError("Source and Destination buffers can't be the same");
        return;
    }

    if (_src_size == 0 || _src_count == 0)
    {
        // Nothing to copy...
        return;
    }

    _dest_offset = yyGetInt32(_dest_offset);
    if (_dest_offset < 0)
    {
        _dest_offset = _WrapIndex(_dest_offset, destBuffer.m_Size);
    }

    _dest_stride = yyGetInt32(_dest_stride);

    // Grow destination buffer if possible
    if (destBuffer.m_Type == eBuffer_Format_Grow)
	{
		var destSizeMin = Math.max(
			_dest_offset + _src_size, // First element
			_dest_offset + (_dest_stride * (_src_count - 1)) + _src_size); // Last element
		if (destBuffer.m_Size < destSizeMin)
		{
			destBuffer.yyb_resize(destSizeMin);
		}
	}

    // Copy data
    var srcBytes = new Uint8Array(srcBuffer.m_pRAWUnderlyingBuffer);
    var destBytes = new Uint8Array(destBuffer.m_pRAWUnderlyingBuffer);
    var srcBuffSize = srcBuffer.m_Size;
    var destBuffSize = destBuffer.m_Size;

    for (var i = 0; i < _src_count; ++i)
	{
		for (var j = 0; j < _src_size; ++j)
		{
			var indexFrom = _src_offset + j;
			if ((indexFrom < 0) || (indexFrom >= srcBuffSize))
			{
				if (srcBuffer.m_Type != eBuffer_Format_Wrap)
				{
					// Cannot wrap index in the source buffer...
					return;
				}
				indexFrom = _WrapIndex(indexFrom, srcBuffSize);
			}

			var indexTo = _dest_offset + j;
			if ((indexTo < 0) || (indexTo >= destBuffSize))
			{
				if (destBuffer.m_Type != eBuffer_Format_Wrap)
				{
					// Cannot wrap index in the destination buffer...
					return;
				}
				indexTo = _WrapIndex(indexTo, destBuffSize);
			}

			destBytes[indexTo] = srcBytes[indexFrom];
            destBuffer.m_UsedSize = Math.max(destBuffer.m_UsedSize, indexTo + 1);
		}

		_src_offset += _src_stride;
		_dest_offset += _dest_stride;
	}
}

