yyPhysicsWorld.prototype.SetParticleFlags = function (_ind, _typeflags) {

    if (_ind >= 0 && _ind < this.m_world.GetParticleCount()) {
        
	    var flags = this.m_world.GetParticleFlagsBuffer();	    
	    flags[_ind] = _typeflags;
    }
};

