function ds_map_set(_id,_key,_val) {

    var pMap = g_ActiveMaps.Get(yyGetInt32(_id));
    if (pMap) {
        var origKey = _key;
        _key = yy_getHash(_key);
        if (_key !== origKey) {
            if (pMap.originalKeys == undefined) {
                pMap.originalKeys = new Map();
            } // end if
            pMap.originalKeys.set( _key, origKey );
        } // end if
        pMap.set( _key, _val );
    }
}

// #############################################################################################
/// Function:<summary>
