function draw_triangle(){}
// @if feature("2d")
function draw_triangle_RELEASE(_x1, _y1, _x2, _y2, _x3, _y3, _outline) {

    _x1 = yyGetReal(_x1);
    _y1 = yyGetReal(_y1);
    _x2 = yyGetReal(_x2);
    _y2 = yyGetReal(_y2);
    _x3 = yyGetReal(_x3);
    _y3 = yyGetReal(_y3);

    /*_x1 += 0.5;
    _y1 += 0.5;
    _x2 += 0.5;
    _y2 += 0.5;
    _x3 += 0.5;
    _y3 += 0.5;*/

    if (offsethack != 0.0)
    {
        _x1 += offsethack;
        _y1 += offsethack;
        _x2 += offsethack;
        _y2 += offsethack;
        _x3 += offsethack;
        _y3 += offsethack;
    }

	graphics.globalAlpha = g_GlobalAlpha;
	graphics.lineWidth = 1;
	if (yyGetBool(_outline))
	{
		graphics.strokeStyle = g_GlobalColour_HTML_RGBA;
		graphics._beginPath();
		graphics._moveTo(_x1, _y1);
		graphics._lineTo(_x2, _y2);
		graphics._lineTo(_x3, _y3);
		graphics._lineTo(_x1, _y1);
		graphics._stroke();
		graphics._closePath();
	} else
	{
		// HORRIBLE!!
		graphics.strokeStyle = g_GlobalColour_HTML_RGBA;
		graphics.lineJoin = "bevel";
		graphics.fillStyle = g_GlobalColour_HTML_RGBA;
		graphics._beginPath();
		graphics._moveTo(_x1, _y1);
		graphics._lineTo(_x2, _y2);
		graphics._lineTo(_x3, _y3);
		graphics._lineTo(_x1, _y1);
		graphics._fill();
		graphics._stroke();
		graphics._closePath();
		//graphics.mozImageSmoothingEnabled = true;
		graphics.lineJoin = "miter";
	}

}
