/// Function:<summary>
///             Creates a sprite by copying the given area from the surface with the given id
///          </summary>
///
/// In:		 <param name="_ind"></param>
///			 <param name="x"></param>
///			 <param name="y"></param>
///			 <param name="w"></param>
///			 <param name="h"></param>
