// #############################################################################################
/// Function:<summary>
///          	Check to see if the network is connected
///          </summary>
///
/// Out:	<returns>
///				Always true....
///			</returns>
// #############################################################################################
function os_is_network_connected() 
{ 
    if (navigator != null && navigator != undefined) {
        return navigator["onLine"] ? 1.0 : 0.0;
    }
    return 1.0; 
}


