// Tilemap element functions
function layerTilemapGetElement(tm_element_id)
{
    var room = g_pLayerManager.GetTargetRoomObj();
    var el = g_pLayerManager.GetElementFromID(room, tm_element_id);

    if ((el != null) && (el.m_type === eLayerElementType_Tilemap)) return el;
    return null;
}

function layer_tilemap_get_id( arg1) 
{
    var room = g_pLayerManager.GetTargetRoomObj();
    if (room === null) return MAKE_REF(REFID_TILEMAP,-1);

    var layer = layerGetObj(room, arg1); 
    if(layer!=null)
    {
        var element = g_pLayerManager.GetFirstElementOfType(layer,eLayerElementType_Tilemap);
        if(element!=null && element.m_type == eLayerElementType_Tilemap)
        {
            return MAKE_REF(REFID_TILEMAP,element.m_id);
        }
    }
    return MAKE_REF(REFID_TILEMAP,-1);

};
function layer_tilemap_exists( arg1,arg2) 
{
    var room = g_pLayerManager.GetTargetRoomObj();
    if (room === null) return false;

    var layer = layerGetObj(room, arg1);
    if(layer!=null)
    {
        // did we get a tilemap name, or a tilemap ID?
        var element = g_pLayerManager.GetElementFromIDWithLayer(layer, yyGetInt32(arg2));

        if(element!=null && element.m_type == eLayerElementType_Tilemap)
        {
            return true;
        }
    }
    return false;

};

function layer_tilemap_create( arg1,arg2,arg3,arg4,arg5,arg6) 
{
    var room = g_pLayerManager.GetTargetRoomObj();
    if (room === null) return MAKE_REF(REFID_TILEMAP,-1);;

    var layer = layerGetObj(room, arg1);
   
    if(layer!=null)
    {
        var TileLayer = new CLayerTilemapElement();
      
        TileLayer.m_backgroundIndex = yyGetInt32(arg4);
        TileLayer.m_mapWidth = yyGetInt32(arg5);
        TileLayer.m_mapHeight = yyGetInt32(arg6);
        TileLayer.m_x = yyGetReal(arg2);
        TileLayer.m_y = yyGetReal(arg3);
        TileLayer.m_pTiles=[];

        var numtiles =0;
        numtiles =arg5*arg6; 
        
        for(var i=0;i<numtiles;i++)
        {
           TileLayer.m_pTiles[i]=0;
        }
       // if(pLayer.pName!=undefined) TileLayer.m_name = pLayer.pName;
   
        g_pLayerManager.AddNewElement(room,layer,TileLayer,true);

        return MAKE_REF(REFID_TILEMAP,TileLayer.m_id);
       
    }
    return MAKE_REF(REFID_TILEMAP,-1);
};

function layer_tilemap_set_colmask(tilemap_element,colmask)
{

    var pRoom = g_pLayerManager.GetTargetRoomObj();

	var pLayer = null;
	var el = null;
	var elementAndLayer = g_pLayerManager.GetElementFromID( pRoom,yyGetInt32(tilemap_element));
	if (elementAndLayer != null)
	{
		pLayer = elementAndLayer.m_layer;
		el = elementAndLayer;
	}

    if((el!=null) && (el.m_type ===eLayerElementType_Tilemap)&& (el.m_pTiles != null )&& (pLayer!=null))
	{
        var pBack = g_pBackgroundManager.GetImage(el.m_backgroundIndex);

        var spr = g_pSpriteManager.Get(colmask);



		if (spr!=null && pBack != null)
        {
            var basespr = g_pSpriteManager.Get(pBack.spriteindex);

            if(basespr!=null)
            {
                if(spr.GetWidth() != basespr.GetWidth() || spr.GetHeight() != basespr.GetHeight())
                {
                    yyError("layer_tilemap_set_colmask size mismatch, expecting " + basespr.GetWidth() + " by "+basespr.GetHeight() + " and received " +spr.GetWidth() + " by " +spr.GetHeight()); 
                }
                el.m_colMask = colmask;
                return 0
            }

        }
    }
    return -1;
}

function layer_tilemap_get_colmask(tilemap_element)
{
    var pRoom = g_pLayerManager.GetTargetRoomObj();

	var pLayer = null;
	var el = null;
	var elementAndLayer = g_pLayerManager.GetElementFromID( pRoom,yyGetInt32(tilemap_element));
	if (elementAndLayer != null)
	{
		pLayer = elementAndLayer.m_layer;
		el = elementAndLayer;
	}

    if((el!=null) && (el.m_type ===eLayerElementType_Tilemap)&& (el.m_pTiles != null )&& (pLayer!=null))
	{
        if(el.m_colMask>=0)
            return el.m_colMask;

        var pBack = g_pBackgroundManager.GetImage(el.m_backgroundIndex);

		if (pBack != null)
            return pBack.spriteindex;

    }
    return -1;
}

