/// In:		 <param name="_fname"></param>
/// Out:	 <returns>
///				
///			 </returns>
// #############################################################################################
function filename_name(_fname) 
{
    _fname = yyGetString(_fname);

	var a = _fname.lastIndexOf( '\\' );
	var b = _fname.lastIndexOf( '/' );
	var last = (a > b) ? a : b;

	var ret = _fname;
	if (last > 0) {
		ret = _fname.substr( last+1 );
	} // end if

    return ret;
}


