// #############################################################################################
/// Function:<summary>
///          	Set the world, view, projection matrix
///          </summary>
///
/// In:		<param name="_type">0 to 2 matrix type</param>
///    		<param name="_matrix">float array</param>
/// Out:	<returns>
///				
///			</returns>
// #############################################################################################
function WebGL_Matrix_Build(_x,_y,_z, _xrot,_yrot,_zrot, _xscale,_yscale,_zscale,_resmat) {

    var m = new Matrix();
    var pi_180 = (Math.PI/180.0);
    _xrot = (pi_180 * -yyGetReal(_xrot));
    _yrot = (pi_180 * -yyGetReal(_yrot));
    _zrot = (pi_180 * -yyGetReal(_zrot));
    m.BuildMatrix(yyGetReal(_x), yyGetReal(_y), yyGetReal(_z), _xrot, _yrot, _zrot, yyGetReal(_xscale), yyGetReal(_yscale), yyGetReal(_zscale));

    if (_resmat == undefined) {
        var mat = [];
        for (var i = 0; i < 16; i++) {
            mat[i] = m.m[i];
        }
        return mat;
    }
    else 
    {
        if(!Array.isArray(_resmat) )
            yyError("matrix_build : result_matrix is not an array");

        for (var i = 0; i < 16; i++) {
            _resmat[i] = m.m[i];
        }
    }
}


// #############################################################################################
/// Function:<summary>
///          	Set the world, view, projection matrix
///          </summary>
///
/// In:		<param name="_type">0 to 2 matrix type</param>
///    		<param name="_matrix">float array</param>
/// Out:	<returns>
///				
///			</returns>
// #############################################################################################
function WebGL_Matrix_Multiply(_s1,_s2,_resmat) {

    var s1 = new Matrix();
    var s2 = new Matrix();
    var s3 = new Matrix();

    for (var i = 0; i < 16; i++) {
        s1.m[i] = yyGetReal(_s1[i]);
        s2.m[i] = yyGetReal(_s2[i]);
    }
    s3.Multiply(s1, s2);

    if(_resmat == undefined)
    {

        var mat = [];
        for (var i = 0; i < 16; i++) {
            mat[i] = s3.m[i];
        }
        return mat;
    }
    else
    {
        if(!Array.isArray(_resmat) )
            yyError("matrix_multiply : result_matrix is not an array");

        for (var i = 0; i < 16; i++) {
            _resmat[i] = s3.m[i];
        }
    }
}

function WebGL_Matrix_Transform_Vertex(_mat, _x, _y, _z)
{
    _x = yyGetReal(_x);
    _y = yyGetReal(_y);
    _z = yyGetReal(_z);

    if (arguments.length == 4)
    {
        var xx = (_mat[_11]*_x) + (_mat[_21]*_y) + (_mat[_31]*_z) + _mat[_41];
        var yy = (_mat[_12]*_x) + (_mat[_22]*_y) + (_mat[_32]*_z) + _mat[_42];
        var zz = (_mat[_13]*_x) + (_mat[_23]*_y) + (_mat[_33]*_z) + _mat[_43];

        return [xx, yy, zz];
    }
    else if (arguments.length == 5 || arguments.length == 6)
    {
        var _w = arguments[4] == undefined ? 1 : yyGetReal(arguments[4]);

        var xx = (_mat[_11]*_x) + (_mat[_21]*_y) + (_mat[_31]*_z) + (_mat[_41]*_w);
        var yy = (_mat[_12]*_x) + (_mat[_22]*_y) + (_mat[_32]*_z) + (_mat[_42]*_w);
        var zz = (_mat[_13]*_x) + (_mat[_23]*_y) + (_mat[_33]*_z) + (_mat[_43]*_w);
        var ww = (_mat[_14]*_x) + (_mat[_24]*_y) + (_mat[_34]*_z) + (_mat[_44]*_w);

        if (arguments[6] != undefined) {
            var _res = arguments[6];

            if(!Array.isArray(_res) )
                yyError("matrix_transform_vertex : result_array is not an array");

            _res[0] = xx;
            _res[1] = yy;
            _res[2] = zz;
            _res[3] = ww;
        } else {
           return [xx, yy, zz, ww];
        }
    }
}

function WebGL_Matrix_Inverse(_s1,_resmat) {

    var s1 = new Matrix();
    var inv_s1 = new Matrix();    

    for (var i = 0; i < 16; i++) {
        s1.m[i] = yyGetReal(_s1[i]);        
    }
    var success = inv_s1.Invert(s1);
    if (!success)
    {
        return undefined;
    }

    
    if (_resmat == undefined) {
        var mat = [];
        for (var i = 0; i < 16; i++) {
            mat[i] = inv_s1.m[i];
        }
        return mat;
    }
    else
    {
        if(!Array.isArray(_resmat) )
            yyError("matrix_inverse : result_matrix is not an array");

        for (var i = 0; i < 16; i++) {
            _resmat[i] = inv_s1.m[i];
        }
    }
}

function WebGL_matrix_stack_push(_matrix)
{
    if (g_matstacktop >= g_maxmatstack)
    {
        // Already at top of stack
        return;
    }

    g_matstacktop++;

    if (arguments.length == 0)
    {
        g_matstack[g_matstacktop] = new Matrix(g_matstack[g_matstacktop-1]);    // if no matrix passed in, copy the previous top of the stack
    }
    else
    {
        var mat = new Matrix();
        var i;
        for(i = 0; i < 16; i++)
        {
            mat.m[i] = _matrix[i];
        }
        
        g_matstack[g_matstacktop] = new Matrix();
        g_matstack[g_matstacktop].Multiply(mat, g_matstack[g_matstacktop-1]);
    }
}

function WebGL_matrix_stack_pop()
{
    g_matstacktop--;

    if (g_matstacktop < 0)
    {
        WebGL_matrix_stack_clear();
    }   
}

function WebGL_matrix_stack_clear()
{
    g_matstacktop = 0;
    g_matstack[0] = new Matrix();    // reset the first matrix in the stack to be unit
}

function WebGL_matrix_stack_set(_matrix)
{
    g_matstack[g_matstacktop] = new Matrix(_matrix);
}

function WebGL_matrix_stack_top()
{
    var elements = new Array(16);
    var i;
    for(i = 0; i < 16; i++)
    {
        elements[i] = g_matstack[g_matstacktop].m[i];
    }

    return elements;
}

function WebGL_matrix_stack_is_empty()
{
    if (g_matstacktop == 0)
        return true;
    else
        return false;
}

