    // #############################################################################################
    /// Function:<summary>
    ///          </summary>
    // ############################################################################################# 
    /** @this {yyWebGL} */
    this.GetUniformIndex = function (_shader, _const) {

        var uniformData = _shader.UniformCache[_const];
        if (uniformData) {
            return uniformData.index;
        }
        return -1;
    };


