    this.SetUniformArrayF = function (_handle, _shaderData)
    {
        if (_handle != -1)
        {
            m_VBufferManager.Flush();
            _shaderData =this.CopyArray(_handle, _shaderData);
            m_CommandBuilder.SetUniformArrayF(_handle, _shaderData);        // shader data already copied
        }
    };
    
